import pandas as pd
import altair as alt
import streamlit as st

def acc():
    data = pd.DataFrame({
    'City': ['Delhi', 'Mumbai', 'Bangalore', 'Chennai', 'Kolkata'],
    'Avg Price (in Lakh)': [78, 95, 82, 70 , 65]
})

    chart = alt.Chart(data).mark_bar().encode(
    x='City',
    y='Avg Price (in Lakh)',
    color='City'
).properties(title='📈 Average House Prices')

    st.altair_chart(chart, use_container_width=True)
    st.subheader("🏡 Featured Listings")
    cols = st.columns(3)
    images = [
    #Property 1
    "data:image/jpeg;base64,",
    
    #Property 2

    "data:image/jpeg;base64,",
   
   #Property 3
   
    "data:image/jpeg;base64,",

    #Picture4

    "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQDQI_8I8f_ijMusPDK9qJIui1k5WbMPM8rmA&s",

    #picture5

    "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRC5wo9ey9STe4WAQTVVJFViAEYi1quKwhBNg&s",
   
    #picture 6

    "data:image/jpeg;base64,"
    
    
    ]

    for i, img in enumerate(images):
       with cols[i % 3]:
         st.image(img, use_container_width=True)
         


    ## Request an Enquiry

    st.subheader("📋 Enquiry Form")  

    with st.form("📋 Enquiry Form", clear_on_submit=True):
        col1, col2 = st.columns(2)
    
    with col1:
        name = st.text_input("👤 Name")
        email = st.text_input("📧 Email")
        submitted = st.form_submit_button("Submit")

    with col2:
        phone = st.text_input("📱 Phone Number")
        preferred_time = st.selectbox("🕒 Preferred Time", ["Morning", "Afternoon", "Evening"])
        
        
        if submitted:
          if not phone.isdigit() or len(phone) != 10:
            st.error("❌ Please enter a valid 10-digit phone number.")
        if submitted:
            st.success(f"Will contact you in prefered time")

